spec.setup_code:
var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var x = W/2 + Math.sin(t * 0.05) * 100;
                    var y = H/2 + Math.cos(t * 0.05) * 100;
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 20, 0, Math.PI * 2);
                    ctx.fill();
                  }
                };

var scale = 1;
              function toScreen(x, y, w, h) {
                scale = Math.min(w, h) / 24;
                return { sx: w / 2 + x * scale, sy: h / 2 - y * scale };
              }
              return {
                draw: function(ctx, w, h) {
                  ctx.clearRect(0, 0, w, h);
                  ctx.strokeStyle = '#E5E7EB';
                  ctx.lineWidth = 1;
                  for (var gx = -10; gx <= 10; gx += 2) {
                    var p1 = toScreen(gx, -10, w, h);
                    var p2 = toScreen(gx, 10, w, h);
                    ctx.beginPath(); ctx.moveTo(p1.sx, p1.sy); ctx.lineTo(p2.sx, p2.sy); ctx.stroke();
                  }
                  for (var gy = -10; gy <= 10; gy += 2) {
                    var p3 = toScreen(-10, gy, w, h);
                    var p4 = toScreen(10, gy, w, h);
                    ctx.beginPath(); ctx.moveTo(p3.sx, p3.sy); ctx.lineTo(p4.sx, p4.sy); ctx.stroke();
                  }
                  var origin = toScreen(0, 0, w, h);
                  ctx.strokeStyle = '#9CA3AF';
                  ctx.lineWidth = 2;
                  ctx.beginPath(); ctx.moveTo(0, origin.sy); ctx.lineTo(w, origin.sy); ctx.stroke();
                  ctx.beginPath(); ctx.moveTo(origin.sx, 0); ctx.lineTo(origin.sx, h); ctx.stroke();
                  ctx.fillStyle = '#374151';
                  ctx.font = '12px sans-serif';
                  ctx.fillText('origin (0,0)', origin.sx + 6, origin.sy - 6);

                  var x = controls.x;
                  var y = controls.y;
                  var pos = toScreen(x, y, w, h);
                  ctx.strokeStyle = '#E8593C';
                  ctx.lineWidth = 2;
                  ctx.setLineDash([5, 4]);
                  ctx.beginPath(); ctx.moveTo(origin.sx, origin.sy); ctx.lineTo(pos.sx, pos.sy); ctx.stroke();
                  ctx.setLineDash([]);
                  ctx.fillStyle = '#E8593C';
                  ctx.beginPath(); ctx.arc(pos.sx, pos.sy, 8, 0, Math.PI * 2); ctx.fill();
                  ctx.fillStyle = '#111827';
                  ctx.font = 'bold 13px sans-serif';
                  ctx.fillText('(' + x.toFixed(1) + ', ' + y.toFixed(1) + ') m', pos.sx + 12, pos.sy - 10);
                }
              };
